import ui_draw as _d
import ui_fonts as _f

WIDTH = 320
HEIGHT = 240

DEFAULTS = {
    "weather_icon": "/img/sun.bin",  # str, < 32 chars
    "temperature": 21.5,  # float, -20…40
}


class UI(_d.Page):
    BACKGROUND = 0xC408  # #0b1a22
    DEFAULTS = DEFAULTS
    # Widgets that can show an animation folder: ("id", loop).
    ANIMS = (("icon", True), ("spinner", True), ("loading", False),)
    USES_ALPHA = True  # a second region buffer for translucent widgets
    # (id, x, y, w, h, parameters) in layer order: the first one is the lowest.
    WIDGETS = (
        ("icon", 20, 20, 64, 64, ("weather_icon",)),
        ("t_val", 100, 30, 203, 48, ("temperature",)),
        ("logo", 20, 100, 120, 60, ()),
        ("logo_small", 160, 100, 60, 30, ()),
        ("spinner", 240, 96, 64, 64, ()),
        ("loading", 20, 190, 128, 32, ()),
        ("ghost", 180, 180, 48, 48, ()),
    )

    def play_icon(self):
        """Restart the animation of "icon" from its first frame."""
        return self.play("icon")

    def play_spinner(self):
        """Restart the animation of "spinner" from its first frame."""
        return self.play("spinner")

    def play_loading(self):
        """Restart the animation of "loading" from its first frame."""
        return self.play("loading")

    def set_weather_icon(self, value):
        self.p["weather_icon"] = value
        return self.update()

    def set_temperature(self, value):
        self.p["temperature"] = value
        return self.update()

    def _draw_icon(self, fb, ox, oy):
        # redrawn when changed: weather_icon
        p = self.p
        path = p["weather_icon"]
        info = self._anim_icon()
        if info is not None:
            path = _d.frame_path(info[0], self.frame("icon"))
        _d.image(fb, 20 - ox, 20 - oy, 64, 64, path)

    def _anim_icon(self):
        return _d.anim_info(self.p["weather_icon"])

    def _draw_t_val(self, fb, ox, oy):
        # redrawn when changed: temperature
        p = self.p
        _d.label(
            fb,
            _d.fmt("%.1f°C", p["temperature"]),
            100 - ox,
            30 - oy,
            200,
            48,
            0xFFFF,
            _f.SERIF_40,
            _d.LEFT,
        )

    def _draw_logo(self, fb, ox, oy):
        _d.image(fb, 20 - ox, 100 - oy, 120, 60, "/img/logo_120x60_cover.bin")

    def _draw_logo_small(self, fb, ox, oy):
        _d.image(fb, 160 - ox, 100 - oy, 60, 30, "/img/logo_60x30.bin")

    def _draw_spinner(self, fb, ox, oy):
        _d.image(
            fb,
            240 - ox,
            96 - oy,
            64,
            64,
            _d.frame_path("/img/spinner/", self.frame("spinner")),
        )

    def _anim_spinner(self):
        return ("/img/spinner/", 12, 80)

    def _draw_loading(self, fb, ox, oy):
        _d.image(
            fb,
            20 - ox,
            190 - oy,
            128,
            32,
            _d.frame_path("/img/loading_128x32_fill/", self.frame("loading")),
        )

    def _anim_loading(self):
        return ("/img/loading_128x32_fill/", 8, 150)

    def _draw_ghost(self, fb, ox, oy):
        fb = self.begin_alpha(fb)  # opacity 60 %
        _d.image(fb, 180 - ox, 180 - oy, 48, 48, "/img/sun_48x48.bin")
        self.end_alpha(19)
